package com.bank.security.controller;

import com.bank.customer.dto.*;
import com.bank.customer.entity.*;
import com.bank.customer.repository.*;
import com.bank.customer.service.AuthCustomerService;
import com.bank.security.dto.*;
import jakarta.validation.Valid;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import java.util.*;

@RestController
@RequestMapping("/api/v1")
public class AuthCustomerController {
    private final AuthCustomerService service; private final UserRepository users; private final RoleDefinitionRepository roles; private final BranchRepository branches; private final ClassificationTypeRepository classifications; private final EmployeeProfileRepository employees; private final CustomerProfileRepository customerProfiles; private final IdentityProofRepository proofs; private final CustomerAddressRepository addresses; private final CustomerPhoneRepository phones; private final CustomerEmailRepository emails;
    public AuthCustomerController(AuthCustomerService service, UserRepository users, RoleDefinitionRepository roles, BranchRepository branches, ClassificationTypeRepository classifications, EmployeeProfileRepository employees, CustomerProfileRepository customerProfiles, IdentityProofRepository proofs, CustomerAddressRepository addresses, CustomerPhoneRepository phones, CustomerEmailRepository emails){this.service=service;this.users=users;this.roles=roles;this.branches=branches;this.classifications=classifications;this.employees=employees;this.customerProfiles=customerProfiles;this.proofs=proofs;this.addresses=addresses;this.phones=phones;this.emails=emails;}

    @PostMapping("/auth/register") public ResponseEntity<JwtResponse> register(@Valid @RequestBody AuthRegisterRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(request));}
    @PostMapping("/auth/login") public JwtResponse login(@Valid @RequestBody LoginRequest request){return service.login(request);}
    @PostMapping("/auth/refresh") public JwtResponse refresh(Authentication authentication){return service.refresh(authentication);}
    @PostMapping("/auth/logout") public ResponseEntity<Void> logout(){return ResponseEntity.noContent().build();}
    @GetMapping("/auth/me") public CustomerResponse me(Authentication authentication){return service.me(authentication.getName());}
    @PostMapping("/auth/change-password") public ResponseEntity<Void> changePassword(Authentication a,@Valid @RequestBody ChangePasswordRequest request){service.changePassword(a.getName(),request);return ResponseEntity.noContent().build();}

    @GetMapping("/users") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Page<Map<String,Object>> users(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return users.findAll(org.springframework.data.domain.PageRequest.of(page,size,org.springframework.data.domain.Sort.by("id").ascending())).map(this::userView);}
    @GetMapping("/users/{userId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Map<String,Object> user(@PathVariable Long userId){return userView(users.findById(userId).orElseThrow());}
    @PatchMapping("/users/{userId}/status") @PreAuthorize("hasRole('ADMIN')") public Map<String,Object> userStatus(@PathVariable Long userId,@RequestBody Map<String,String> body){User user=userEntity(userId);user.setStatus(body.getOrDefault("status","ACTIVE"));return userView(users.save(user));}
    @GetMapping("/roles") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<RoleDefinition> roles(){return roles.findAll();}
    @PostMapping("/roles") @PreAuthorize("hasRole('ADMIN')") public RoleDefinition createRole(@Valid @RequestBody RoleRequest req){RoleDefinition role=new RoleDefinition();role.setCode(req.getCode());role.setName(req.getName());role.setDescription(req.getDescription());return roles.save(role);}
    @PutMapping("/roles/{roleId}") @PreAuthorize("hasRole('ADMIN')") public RoleDefinition updateRole(@PathVariable Long roleId,@Valid @RequestBody RoleRequest req){RoleDefinition role=roles.findById(roleId).orElseThrow();role.setCode(req.getCode());role.setName(req.getName());role.setDescription(req.getDescription());return roles.save(role);}
    @PostMapping("/users/{userId}/roles") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> assignRole(@PathVariable Long userId,@RequestParam Long roleId){User user=userEntity(userId);UserRole assignment=new UserRole();assignment.setUser(user);assignment.setRole(roles.findById(roleId).orElseThrow());user.getRoleAssignments().add(assignment);users.save(user);return ResponseEntity.noContent().build();}
    @GetMapping("/users/{userId}/roles") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<String> userRoles(@PathVariable Long userId){return userEntity(userId).getAuthorities().stream().map(a->a.getAuthority()).toList();}
    @DeleteMapping("/users/{userId}/roles/{roleId}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> removeRole(@PathVariable Long userId,@PathVariable Long roleId){User user=userEntity(userId);user.getRoleAssignments().removeIf(a->a.getRole()!=null && roleId.equals(a.getRole().getId()));users.save(user);return ResponseEntity.noContent().build();}
    @GetMapping("/employees") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<EmployeeProfile> employees(){return employees.findAll();}
    @GetMapping("/employees/search") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Page<EmployeeProfile> searchEmployees(@RequestParam String q,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return employees.findByFullNameContainingIgnoreCaseOrEmployeeCodeContainingIgnoreCase(q,q,PageRequest.of(Math.max(page,0),Math.max(size,1),Sort.by("id").ascending()));}
    @PostMapping("/employees") @PreAuthorize("hasRole('ADMIN')") public EmployeeProfile createEmployee(@Valid @RequestBody EmployeeProfileRequest req){EmployeeProfile emp=new EmployeeProfile();emp.setUser(userEntity(req.getUserId()));emp.setEmployeeCode(req.getEmployeeCode());emp.setFullName(req.getFullName());emp.setDesignation(req.getDesignation());emp.setHomeBranchId(req.getHomeBranchId());emp.setDateOfJoining(req.getDateOfJoining());emp.setDateOfLeaving(req.getDateOfLeaving());return employees.save(emp);}
    @GetMapping("/employees/{employeeProfileId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public EmployeeProfile employee(@PathVariable Long employeeProfileId){return employees.findById(employeeProfileId).orElseThrow();}
    @PutMapping("/employees/{employeeProfileId}") @PreAuthorize("hasRole('ADMIN')") public EmployeeProfile updateEmployee(@PathVariable Long employeeProfileId,@Valid @RequestBody EmployeeProfileRequest req){EmployeeProfile emp=employees.findById(employeeProfileId).orElseThrow();emp.setEmployeeCode(req.getEmployeeCode());emp.setFullName(req.getFullName());emp.setDesignation(req.getDesignation());emp.setHomeBranchId(req.getHomeBranchId());emp.setDateOfJoining(req.getDateOfJoining());emp.setDateOfLeaving(req.getDateOfLeaving());return employees.save(emp);}
    @GetMapping("/branches") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<Branch> branches(){return branches.findAll();}
    @PostMapping("/branches") @PreAuthorize("hasRole('ADMIN')") public Branch createBranch(@Valid @RequestBody BranchRequest req){Branch b=new Branch();b.setCode(req.getCode());b.setName(req.getName());b.setCity(req.getCity());if(req.getActive()!=null)b.setActive(req.getActive());return branches.save(b);}
    @GetMapping("/branches/{branchId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Branch branch(@PathVariable Long branchId){return branches.findById(branchId).orElseThrow();}
    @PutMapping("/branches/{branchId}") @PreAuthorize("hasRole('ADMIN')") public Branch updateBranch(@PathVariable Long branchId,@Valid @RequestBody BranchRequest req){Branch b=branches.findById(branchId).orElseThrow();b.setCode(req.getCode());b.setName(req.getName());b.setCity(req.getCity());return branches.save(b);}
    @PatchMapping("/branches/{branchId}/status") @PreAuthorize("hasRole('ADMIN')") public Branch updateBranchStatus(@PathVariable Long branchId,@RequestBody Map<String,Boolean> body){Branch b=branches.findById(branchId).orElseThrow();b.setActive(Boolean.TRUE.equals(body.get("active")));return branches.save(b);}
    @GetMapping("/customer-classification-types") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<ClassificationType> classifications(){return classifications.findAll();}
    @PostMapping("/customer-classification-types") @PreAuthorize("hasRole('ADMIN')") public ClassificationType createClassification(@RequestBody ClassificationType type){return classifications.save(type);}
    @PutMapping("/customer-classification-types/{typeId}") @PreAuthorize("hasRole('ADMIN')") public ClassificationType updateClassification(@PathVariable Long typeId,@RequestBody ClassificationType update){ClassificationType type=classifications.findById(typeId).orElseThrow();type.setCode(update.getCode());type.setName(update.getName());return classifications.save(type);}
    @PatchMapping("/customer-classification-types/{typeId}/status") @PreAuthorize("hasRole('ADMIN')") public ClassificationType updateClassificationStatus(@PathVariable Long typeId,@RequestBody Map<String,Boolean> body){ClassificationType type=classifications.findById(typeId).orElseThrow();type.setActive(Boolean.TRUE.equals(body.get("active")));return classifications.save(type);}

    @PostMapping("/customers") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerResponse createCustomer(@Valid @RequestBody CustomerCreateRequest request){User user=userEntity(request.getUserId());CustomerProfile profile=new CustomerProfile();profile.setUser(user);profile.setCustomerNumber(request.getCustomerNumber()==null?"CUS-"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase():request.getCustomerNumber());profile.setLegalEntityType(request.getLegalEntityType());profile.setKycStatus(request.getKycStatus()==null?"PENDING":request.getKycStatus());profile.setRiskCategory(request.getRiskCategory());CustomerDetails details=new CustomerDetails();details.setFullName(request.getFullName()==null?user.getUsername():request.getFullName());profile.setDetails(details);return serviceResponse(customerProfiles.save(profile));}
    @GetMapping("/customers") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Page<CustomerResponse> listCustomers(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(required=false) String status,@RequestParam(required=false) String risk,@RequestParam(required=false) String search){return service.customers(page,size,status,risk,search);}
    @GetMapping("/customers/search") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Page<CustomerResponse> search(@RequestParam String q,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return service.customers(page,size,null,null,q);}
    @GetMapping("/customers/by-user/{userId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerResponse byUser(@PathVariable Long userId){return service.getCustomerByUserId(userId);}
    @GetMapping("/customers/{customerId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerResponse customer(@PathVariable Long customerId){return service.getCustomer(customerId);}
    @PutMapping("/customers/{customerId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerResponse updateCustomer(@PathVariable Long customerId,@RequestBody CustomerUpdateRequest request){CustomerProfile profile=profile(customerId);if(request.getLegalEntityType()!=null)profile.setLegalEntityType(request.getLegalEntityType());if(request.getKycStatus()!=null)profile.setKycStatus(request.getKycStatus());if(request.getRiskCategory()!=null)profile.setRiskCategory(request.getRiskCategory());if(request.getFullName()!=null){if(profile.getDetails()==null)profile.setDetails(new CustomerDetails());profile.getDetails().setFullName(request.getFullName());}return serviceResponse(customerProfiles.save(profile));}
    @PatchMapping("/customers/{customerId}/status") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerResponse status(@PathVariable Long customerId,@RequestBody Map<String,String> body){service.updateStatus(customerId,body.get("status"),body.get("riskCategory"));return service.getCustomer(customerId);}
    @PatchMapping("/customers/{customerId}/risk-category") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerResponse riskCategory(@PathVariable Long customerId,@RequestBody Map<String,String> body){service.updateStatus(customerId,null,body.get("riskCategory"));return service.getCustomer(customerId);}
    @GetMapping("/customers/{customerId}/details") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerDetailsDto details(@PathVariable Long customerId){return detailsResponse(profile(customerId));}
    @PutMapping("/customers/{customerId}/details") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerDetailsDto updateDetails(@PathVariable Long customerId,@RequestBody CustomerDetailsDto update){CustomerProfile profile=profile(customerId);CustomerDetails details=profile.getDetails();if(details==null){details=new CustomerDetails();profile.setDetails(details);}details.setFullName(update.getFullName());details.setDateOfBirth(update.getDateOfBirth());details.setFatherOrSpouseName(update.getFatherOrSpouseName());details.setOccupation(update.getOccupation());customerProfiles.save(profile);return detailsResponse(profile);}
    @GetMapping({"/customers/{customerId}/eligibility","/internal/customers/{customerId}/eligibility"}) @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Map<String,Object> eligibility(@PathVariable Long customerId){service.getCustomer(customerId);return Map.of("eligible",true,"customerId",customerId);}
    @GetMapping("/customers/{customerId}/identity-proofs") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<IdentityProof> proofs(@PathVariable Long customerId){profile(customerId);return proofs.findByCustomerId(customerId);}
    @PostMapping("/customers/{customerId}/identity-proofs") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public IdentityProof addProof(@PathVariable Long customerId,@Valid @RequestBody IdentityProofRequest req){IdentityProof proof=new IdentityProof();proof.setCustomer(profile(customerId));proof.setProofType(classifications.findById(req.getProofTypeId()).orElseThrow(()->new com.bank.common.exception.ResourceNotFoundException("Classification type not found")));proof.setProofValue(req.getProofValue());proof.setMaskedValue(req.getMaskedValue());proof.setExpiryDate(req.getExpiryDate());proof.setDocumentReference(req.getDocumentReference());return proofs.save(proof);}
    @GetMapping("/customers/{customerId}/identity-proofs/{proofId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public IdentityProof proof(@PathVariable Long customerId,@PathVariable Long proofId){return proofs.findByIdAndCustomerId(proofId,customerId).orElseThrow();}
    @PatchMapping("/customers/{customerId}/identity-proofs/{proofId}/verify") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public IdentityProof verifyProof(@PathVariable Long customerId,@PathVariable Long proofId,@RequestBody Map<String,String> body){IdentityProof proof=proofs.findByIdAndCustomerId(proofId,customerId).orElseThrow();proof.setVerificationStatus(body.getOrDefault("status","VERIFIED"));return proofs.save(proof);}
    @DeleteMapping("/customers/{customerId}/identity-proofs/{proofId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public ResponseEntity<Void> deleteProof(@PathVariable Long customerId,@PathVariable Long proofId){IdentityProof proof=proofs.findByIdAndCustomerId(proofId,customerId).orElseThrow();proofs.delete(proof);return ResponseEntity.noContent().build();}
    @GetMapping("/customers/{customerId}/addresses") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<CustomerAddress> addresses(@PathVariable Long customerId){profile(customerId);return addresses.findByCustomerId(customerId);}
    @PostMapping("/customers/{customerId}/addresses") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerAddress addAddress(@PathVariable Long customerId,@RequestBody AddressRequest req){CustomerAddress address=new CustomerAddress();address.setCustomer(profile(customerId));address.setAddressType(req.getAddressType());address.setCity(req.getCity());address.setPostalCode(req.getPostalCode());return addresses.save(address);}
    @PutMapping("/customers/{customerId}/addresses/{addressId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerAddress updateAddress(@PathVariable Long customerId,@PathVariable Long addressId,@RequestBody AddressRequest req){CustomerAddress address=addresses.findByIdAndCustomerId(addressId,customerId).orElseThrow();address.setAddressType(req.getAddressType());address.setCity(req.getCity());address.setPostalCode(req.getPostalCode());return addresses.save(address);}
    @DeleteMapping("/customers/{customerId}/addresses/{addressId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public ResponseEntity<Void> deleteAddress(@PathVariable Long customerId,@PathVariable Long addressId){addresses.delete(addresses.findByIdAndCustomerId(addressId,customerId).orElseThrow());return ResponseEntity.noContent().build();}
    @PatchMapping("/customers/{customerId}/addresses/{addressId}/primary") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerAddress primaryAddress(@PathVariable Long customerId,@PathVariable Long addressId){CustomerAddress address=addresses.findByIdAndCustomerId(addressId,customerId).orElseThrow();address.setPrimaryAddress(true);return addresses.save(address);}
    @PatchMapping("/customers/{customerId}/addresses/{addressId}/verify") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerAddress verifyAddress(@PathVariable Long customerId,@PathVariable Long addressId){CustomerAddress address=addresses.findByIdAndCustomerId(addressId,customerId).orElseThrow();address.setVerified(true);return addresses.save(address);}
    @GetMapping("/customers/{customerId}/phones") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<CustomerPhone> phones(@PathVariable Long customerId){profile(customerId);return phones.findByCustomerId(customerId);}
    @PostMapping("/customers/{customerId}/phones") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerPhone addPhone(@PathVariable Long customerId,@Valid @RequestBody PhoneRequest req){CustomerPhone phone=new CustomerPhone();phone.setCustomer(profile(customerId));phone.setContactType(req.getContactType());phone.setCountryCode(req.getCountryCode());phone.setPhoneNumber(req.getPhoneNumber());return phones.save(phone);}
    @PutMapping("/customers/{customerId}/phones/{phoneId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerPhone updatePhone(@PathVariable Long customerId,@PathVariable Long phoneId,@Valid @RequestBody PhoneRequest req){CustomerPhone phone=phones.findByIdAndCustomerId(phoneId,customerId).orElseThrow();phone.setContactType(req.getContactType());phone.setCountryCode(req.getCountryCode());phone.setPhoneNumber(req.getPhoneNumber());return phones.save(phone);}
    @DeleteMapping("/customers/{customerId}/phones/{phoneId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public ResponseEntity<Void> deletePhone(@PathVariable Long customerId,@PathVariable Long phoneId){phones.delete(phones.findByIdAndCustomerId(phoneId,customerId).orElseThrow());return ResponseEntity.noContent().build();}
    @PatchMapping("/customers/{customerId}/phones/{phoneId}/primary") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerPhone primaryPhone(@PathVariable Long customerId,@PathVariable Long phoneId){CustomerPhone phone=phones.findByIdAndCustomerId(phoneId,customerId).orElseThrow();phone.setPrimaryPhone(true);return phones.save(phone);}
    @PatchMapping("/customers/{customerId}/phones/{phoneId}/verify") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerPhone verifyPhone(@PathVariable Long customerId,@PathVariable Long phoneId){CustomerPhone phone=phones.findByIdAndCustomerId(phoneId,customerId).orElseThrow();phone.setVerified(true);return phones.save(phone);}
    @GetMapping("/customers/{customerId}/emails") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<CustomerEmail> emails(@PathVariable Long customerId){profile(customerId);return emails.findByCustomerId(customerId);}
    @PostMapping("/customers/{customerId}/emails") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerEmail addEmail(@PathVariable Long customerId,@Valid @RequestBody EmailRequest req){CustomerEmail email=new CustomerEmail();email.setCustomer(profile(customerId));email.setContactType(req.getContactType());email.setEmailAddress(req.getEmailAddress());return emails.save(email);}
    @PutMapping("/customers/{customerId}/emails/{emailId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerEmail updateEmail(@PathVariable Long customerId,@PathVariable Long emailId,@Valid @RequestBody EmailRequest req){CustomerEmail email=emails.findByIdAndCustomerId(emailId,customerId).orElseThrow();email.setContactType(req.getContactType());email.setEmailAddress(req.getEmailAddress());return emails.save(email);}
    @DeleteMapping("/customers/{customerId}/emails/{emailId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public ResponseEntity<Void> deleteEmail(@PathVariable Long customerId,@PathVariable Long emailId){emails.delete(emails.findByIdAndCustomerId(emailId,customerId).orElseThrow());return ResponseEntity.noContent().build();}
    @PatchMapping("/customers/{customerId}/emails/{emailId}/primary") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerEmail primaryEmail(@PathVariable Long customerId,@PathVariable Long emailId){CustomerEmail email=emails.findByIdAndCustomerId(emailId,customerId).orElseThrow();email.setPrimaryEmail(true);return emails.save(email);}
    @PatchMapping("/customers/{customerId}/emails/{emailId}/verify") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public CustomerEmail verifyEmail(@PathVariable Long customerId,@PathVariable Long emailId){CustomerEmail email=emails.findByIdAndCustomerId(emailId,customerId).orElseThrow();email.setVerified(true);return emails.save(email);}

    @PostMapping("/internal/auth/validate") public Map<String,Object> validate(Authentication authentication){return Map.of("valid",authentication!=null&&authentication.isAuthenticated(),"username",authentication==null?"":authentication.getName());}
    @GetMapping("/internal/auth/users/{userId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Map<String,Object> internalUser(@PathVariable Long userId){return user(userId);}
    @GetMapping("/internal/users/{userId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Map<String,Object> internalUserInfo(@PathVariable Long userId){return user(userId);}
    @GetMapping("/internal/users/{userId}/roles") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public List<String> internalUserRoles(@PathVariable Long userId){return userRoles(userId);}
    @GetMapping("/internal/branches/{branchId}") @PreAuthorize("hasAnyRole('BANK_OFFICER','ADMIN')") public Branch internalBranch(@PathVariable Long branchId){return branch(branchId);}
    private User userEntity(Long id){return users.findById(id).orElseThrow();}
    private com.bank.customer.entity.CustomerProfile profile(Long id){return customerProfiles.findById(id).orElseThrow();}
    private CustomerResponse serviceResponse(CustomerProfile profile){return new CustomerResponse(profile.getId(),profile.getCustomerNumber(),profile.getUser().getUsername(),profile.getDetails()==null?null:profile.getDetails().getFullName(),profile.getKycStatus(),profile.getRiskCategory(),profile.getLegalEntityType());}
    private CustomerDetailsDto detailsResponse(CustomerProfile profile){CustomerDetails details=profile.getDetails();return details==null?new CustomerDetailsDto():new CustomerDetailsDto(details.getFullName(),details.getDateOfBirth(),details.getFatherOrSpouseName(),details.getOccupation());}
    private Map<String,Object> userView(User user){return Map.of("id",user.getId(),"username",user.getUsername(),"status",user.getStatus(),"userType",user.getUserType(),"roles",user.getAuthorities().stream().map(a->a.getAuthority()).toList());}
}